--- app/views/account/settings/_cancellation.html.erb ---
<% if Current.account.cancellable? && Current.user.owner? %>
  <section class="settings__section settings__section--negative">
    <header>
      <h2 class="divider">Danger zone</h2>
      <div>Delete your account and everything in&nbsp;it, including all boards and cards.</div>
    </header>

    <div data-controller="dialog toggle-enable" data-dialog-modal-value="true">
      <button type="button" class="btn btn--negative" data-action="dialog#open">Delete account...</button>

      <dialog class="dialog panel panel--wide shadow" data-dialog-target="dialog" data-action="close->toggle-enable#reset" style="--panel-size: 48ch;">
        <h2 class="margin-none txt-large txt-negative">Delete account</h2>
        <div class="txt-align-start">
          <h3 class="margin-block-start margin-block-end-half txt-normal">What happens next:</h3>
          <ul class="list-unindented margin-block-start-half margin-block-end">
            <li>Your <strong><%= Current.account.name %></strong> account will be closed immediately.</li>
            <li>All users, including you, will lose access.</li>
            <% if Current.account.try(:active_subscription) %>
              <li>Your subscription will be canceled.</li>
            <% end %>
            <li>All your data will be permanently deleted within 30&nbsp;days.</li>
          </ul>

          <h3 class="margin-block-end-half txt-normal">Remember to export your data</h3>
          <p class="margin-block-start-half margin-block-end">
            <button type="button" class="btn btn--plain txt-link" data-controller="dispatch-event" data-dispatch-event-name-value="open-export" data-action="click->dialog#close click->dispatch-event#fire">Export your data</button> before you go. You won’t be able to do it after you delete your account.
          </p>
        </div>

        <label class="flex gap justify-start txt-align-start margin-block-end-double">
          <input type="checkbox" class="checkbox" data-toggle-enable-target="checkbox" data-action="change->toggle-enable#toggle">
          I’ve read the above and want to continue
        </label>

        <div class="flex gap justify-center">
          <button type="button" class="btn" autofocus data-action="dialog#close">Not now</button>
          <%= button_to "Delete my account", account_cancellation_path,
              method: :post,
              class: "btn btn--negative",
              disabled: true,
              form: { data: { action: "submit->dialog#close", turbo: false } },
              data: { toggle_enable_target: "element" } %>
        </div>
      </dialog>
    </div>
  </section>
<% end %>
--- app/views/account/settings/_entropy.html.erb ---
<section class="settings__section">
  <header>
    <h2 class="divider">Auto close</h2>
    <div>Fizzy doesn’t let stale cards stick around forever. Cards automatically move to “Not Now” if there is no activity for a specific period of time. <em>This is the default, global setting — you can override it on each board.</em></div>
  </header>

  <%= render "entropy/auto_close", model: account.entropy, url: account_entropy_path, disabled: !Current.user.admin? %>
</section>
--- app/views/account/settings/_export.html.erb ---
<section class="settings__section">
  <header>
    <h2 class="divider">Export account data</h2>
    <div>Download a complete archive of all account data.</div>
  </header>

  <div data-controller="dialog" data-dialog-modal-value="true" data-action="keydown.esc->dialog#close open-export@document->dialog#open">
    <button type="button" class="btn" data-action="dialog#open">Begin export...</button>

    <dialog class="dialog panel panel--wide shadow" data-dialog-target="dialog" style="--panel-size: 48ch;">
      <h2 class="txt-large">Export all account data</h2>
      <p>This will generate a ZIP archive of all data in this account including all boards, cards, users, and settings.</p>
      <p>We’ll email you a link to download the file when it’s ready. The link will expire after 24 hours.</p>

      <div class="flex gap justify-center">
        <%= button_to "Start export", account_exports_path, method: :post, class: "btn btn--link", form: { data: { action: "submit->dialog#close" } } %>
        <button type="button" class="btn" data-action="dialog#close">Cancel</button>
      </div>
    </dialog>
  </div>
</section>
--- app/views/account/settings/_name.html.erb ---
<section class="settings__section">
  <%= form_with model: account, url: account_settings_path, method: :put, scope: :account, data: { controller: "form" }, class: "flex gap-half" do |form| %>
    <strong class="full-width"><%= form.text_field :name, required: true, class: "input input--transparent full-width txt-medium", placeholder: "Account name…", data: { action: "input->form#disableSubmitWhenInvalid" }, ",
  "output_tail": "settings__panel settings__panel--entropy panel shadow center">
    <%= render "account/settings/entropy", account: @account %>
    <%= render "account/settings/export" if Current.user.admin? || Current.user.owner? %>
    <%= render "account/settings/cancellation" %>
  </div>
</div>
--- app/views/account/settings/show.json.jbuilder ---
json.(@account, :id, :name, :cards_count)
json.created_at @account.created_at.utc
json.auto_postpone_period_in_days @account.entropy.auto_postpone_period_in_days
--- app/controllers/account/settings_controller.rb ---
class Account::SettingsController < ApplicationController
  wrap_parameters :account, include: %i[ name ]

  before_action :ensure_admin, only: :update
  before_action :set_account

  def show
    respond_to do |format|
      format.html { @users = @account.users.active.alphabetically.includes(:identity) }
      format.json
    end
  end

  def update
    @account.update!(account_params)

    respond_to do |format|
      format.html { redirect_to account_settings_path }
      format.json { head :no_content }
    end
  end

  private
    def set_account
      @account = Current.account
    end

    def account_params
      params.expect account: %i[ name ]
    end
end
--- app/controllers/account/entropies_controller.rb ---
class Account::EntropiesController < ApplicationController
  wrap_parameters :entropy, include: [ :auto_postpone_period_in_days ]

  before_action :ensure_admin

  def update
    @account = Current.account
    @account.entropy.update!(entropy_params)

    respond_to do |format|
      format.html { redirect_to account_settings_path, notice: "Account updated" }
      format.json { render "account/settings/show", status: :ok }
    end
  rescue ActiveRecord::RecordInvalid
    head :unprocessable_entity
  end

  private
    def entropy_params
      params.expect(entropy: [ :auto_postpone_period_in_days ])
    end
end
--- app/assets/stylesheets/settings.css ---
@layer components {
  .settings {
    --settings-spacer: var(--block-space);
    --settings-item-padding-inline: 0.5ch;

    align-items: start;
    display: flex;
    gap: calc(var(--settings-spacer) * 2);
    flex-direction: column;
    justify-content: center;
    margin: 0 auto;
    max-inline-size: min(100ch, 100%);

    @media (min-width: 960px) {
      flex-direction: row;

      .settings__panel {
        max-inline-size: 50%;
      }
    }
  }

  /* Sections & Panels
  /* -------------------------------------------------------------------------- */

  .settings__panel {
    --panel-size: 100%;
    --panel-padding: calc(var(--settings-spacer) / 1);

    display: flex;
    flex-direction: column;
    gap: var(--panel-padding);
    min-block-size: 100%;
    min-inline-size: 0;

    @media (min-width: 640px) {
      --panel-padding: calc(var(--settings-spacer) * 2);
    }
  }

  .settings__panel--users {
    @media (min-width: 640px) {
      max-height: 80dvh;
    }

    @media (min-width: 960px) {
      max-height: calc(100dvh - 12rem);
    }
  }

  .settings__section {
    h2 {
      font-size: var(--text-large);
    }

    > * + * {
      margin-block-start: calc(var(--panel-padding) / 2);
    }

    &:is(:first-child):has(h2) {
      margin-top: -0.33lh; /* Align h2 letters caps with panel padding */
    }
  }

  .settings__section--negative {
    h2 {
      color: var(--color-negative);
    }

    .divider {
      --divider-color: oklch(var(--lch-red-light));
    }
  }

  .settings__section:has(.settings__scrollable-list) {
    @media (min-width: 640px) {
      display: flex;
      flex: 1;
      flex-direction: column;
      min-height: 0;
    }
  }

  .settings__scrollable-list {
    flex: 1 1 auto;
    list-style: none;
    margin: calc(var(--settings-spacer) / -4) calc(-1 * var(--settings-item-padding-inline));
    padding: 0;
    overflow: auto;

    li {
      border-radius: 0.5em;

      /* Add padding if it's not already on a link within */
      &:not(:has(a:first-child)) { padding-inline-end: var(--settings-item-padding-inline); }
      &:not(:has(a:last-child)) { padding-inline-end: var(--settings-item-padding-inline); }
    }

    a {
      padding: calc(var(--settings-spacer) / 4) var(--settings-item-padding-inline);

      @media(any-hover: hover) {
        &:hover {
          text-decoration: underline;
        }
      }
    }

    /* Only add a BG color when you can actually navigate */
    .settings__user-filter:focus-within & {
      [aria-selected] {
        background: var(--color-selected);
      }
    }
  }

  /* Users
  /* ------------------------------------------------------------------------ */

  .settings__user-filter {
    --btn-size: 3.5ch;
    --avatar-size: var(--btn-size);

    display: flex;
    flex-direction: column;
    gap: calc(var(--settings-spacer) / 2);
    min-height: 0;
  }

  .settings__user-filter--bg {
    background-color: var(--color-ink-lightest);
    border-radius: 0.5em;
    margin-block: 0;
    padding: var(--settings-spacer);
  }
}
